"""
fichas.py — Texto que muestra el boton (i) de cada metodo en el simulador y su subtitulo corto.
Para anadir un metodo nuevo agrega una entrada con el MISMO id que en metodos.py:
  FICHA["mi_metodo"] = "<p><b>Qué es.</b> ...</p><p><b>Qué se aprendió.</b> ...</p>"     (HTML sencillo: <p>, <b>, <i>)
  SHORT["mi_metodo"] = "Una línea · ~N mediciones"
Si no la agregas, el simulador muestra una ficha genérica. Las cifras de campaña se agregan solas al final de la ficha.
"""
FICHA = {
 "msapso": ("<p><b>Qué es.</b> El algoritmo del paper (Fig. 6): un enjambre de 7 partículas que se reparten entre 0.95 y 0.10 de la corriente de cortocircuito. Cada pasada mide las 7 corrientes (una medición cada una) y acerca las partículas a la mejor posición encontrada con un factor β que crece de 0.1 a 0.95.</p>"
            "<p><b>Cómo termina.</b> Siempre hace 25 pasadas (175 mediciones). Después fija la corriente de la mejor medición y la vigila: si la potencia cambia 5 W o más respecto de la referencia, reinicia la búsqueda. No usa ningún margen de corriente.</p>"
            "<p><b>Para qué está aquí.</b> Es la referencia: todo lo demás se compara contra este método, con el mismo simulador, los mismos escenarios y el mismo ruido.</p>"),
 "v7": ("<p><b>Qué es.</b> El mismo MSAPSO, pero se detiene cuando las 7 partículas ya se agruparon (dispersión menor al 2 % de la corriente de cortocircuito, mínimo 3 pasadas). En promedio usa 70 mediciones en lugar de 175.</p>"
        "<p><b>Por qué importa.</b> Casi no pierde exactitud (0.05 pp en promedio) y deja más tiempo operando en el punto bueno, de ahí su ventaja de energía. Es el <b>método principal</b> del proyecto.</p>"),
 "v7b": ("<p><b>Qué es.</b> La V7, pero al terminar la búsqueda el convertidor se fija en el <b>98 %</b> de la corriente encontrada (retroceso del 2 %).</p>"
         "<p><b>Por qué.</b> A la derecha del pico la potencia cae casi vertical y a la izquierda suave, así que quedarse un poco corto cuesta menos que pasarse. El 2 % se eligió probando 0, 2, 4, 6 y 8 % en escenarios de validación. Es un agregado nuestro: el paper no lo usa. Cuesta algo de exactitud estática y rinde en dinámica.</p>"),
 "cem": ("<p><b>Qué es.</b> Cross-Entropy Method puro (idea propuesta por el profesor): una sola gaussiana sobre la corriente, centrada en 0.5 con σ = 0.3. Cada iteración mide 10 candidatos, se queda con los 3 mejores y reajusta media y σ con ellos; para cuando σ &lt; 0.01 (~59 mediciones).</p>"
         "<p><b>Qué se aprendió.</b> Como buscador global es débil: con varios picos parecidos la gaussiana se contrae sobre uno y puede ser el equivocado. Funciona mucho mejor como <i>refinador local</i> (lo usan la candidata V14 y el MLP + CEM).</p>"),
 "mlp": ("<p><b>Qué es.</b> Un barrido de 7 mediciones, un MLP (2 capas de 64) que predice en qué corriente está el pico y un CEM que lo refina desde ahí (~37 mediciones). El MLP se entrenó por regresión (retropropagación) con 30 000 sombras sintéticas.</p>"
         "<p><b>Qué representa.</b> Es una cota superior de lo que podría lograr el aprendizaje por refuerzo o la neuroevolución con la misma red, porque el entrenamiento supervisado tiene la mejor señal posible. Su ventaja en dinámica se explicó en buena parte por el margen de corriente que elige, que se reproduce sin entrenar nada con el retroceso del 2 %.</p>"),
 "v14": ("<p><b>Qué es.</b> Tres pasadas del MSAPSO (con β comprimida) para ubicar el pico, un CEM (7 candidatos, 2 élites, σ inicial 0.03) para afinarlo y retroceso del 2 % al final. Unas 39 mediciones, sin ningún entrenamiento.</p>"
         "<p><b>Por qué se muestra.</b> Es la que más energía gana en dinámica, pero tiene la peor <i>cola</i> de las competitivas: en algunas sombras elige el pico equivocado y pierde mucho. Por eso no sustituye a la V7. Fíjate en el escenario «Peor caso de la candidata V14».</p>"),
 "dgbco": ("<p><b>Qué es.</b> Dynamic Group-Based Cooperative Optimization (Moosavi et al., Energy Reports 2022): agentes divididos en un grupo de exploración (70 %) y uno de explotación (30 %), con mutaciones y pasos guiados por la mejor posición. Aquí: 4 agentes × 10 iteraciones = 40 mediciones, retroceso del 2 %.</p>"
           "<p><b>Reserva.</b> Varias partes no las precisa el paper y las interpretamos nosotros (inicialización, pertenencia a grupos, recortes). Se probó con las ecuaciones del artículo, sin ajustar más.</p>"),
 "cedgo": ("<p><b>Qué es.</b> CEDGO (Tang, Fong et al., Entropy 2017): el Dynamic Group Optimization de Tang y Fong con un operador de entropía cruzada en los miembros de cada grupo, vuelo de Lévy en las cabezas y tiempo de vida. Aquí: 8 individuos × 5 generaciones = 40 mediciones, retroceso del 2 %. Es la versión que confirmó el profesor.</p>"
           "<p><b>Reserva.</b> Muchas partes se interpretaron (2 grupos, parámetros de mutación, tiempo de vida) y se tomaron las ecuaciones de un artículo posterior al original. Con tan pocas mediciones los grupos no tienen espacio para separarse.</p>"),
 "decent": ("<p><b>Qué es.</b> La versión del profesor de DecentCEM: se miden 10 puntos repartidos en todo el rango de corriente; los mejores se agrupan por separación (umbral 0.15 de la corriente de cortocircuito) y cada grupo se vuelve un <i>worker</i> con su propia gaussiana de σ fija (0.03) que refina su pico con 4 muestras × 4 iteraciones. Al final se queda con el mejor punto medido. Unas 40 mediciones, sin retroceso.</p>"
            "<p><b>Qué se aprendió.</b> Refinar cada pico antes de decidir baja mucho la cola frente a la candidata V14, y dejar σ fija funcionó mejor que adaptarla. Pero con tiempos de espera cortos (0.5 ms) pierde claramente contra la V7, y su ventaja de energía sobre la V7 no es demostrable.</p>"),
}
SHORT = {"msapso": "Referencia del paper · 175 mediciones", "v7": "MSAPSO con parada anticipada · ~70", "v7b": "V7 + corriente al 98 % · ~70", "cem": "Una gaussiana · ~59", "mlp": "MLP supervisado + CEM · ~37",
         "v14": "MSAPSO corto + CEM + 98 % · ~39", "dgbco": "Grupos exploración/explotación · 40", "cedgo": "DGO + entropía cruzada · 40", "decent": "Barrido + workers por pico · ~40"}

# ---------------------------------------------------------------------------------------------------------------
# Revision del profesor (nov. 2026): que mirar en el simulador para cada metodo. Se anade al final de su ficha.
# Los colores por poblacion salen de las etiquetas que cada algoritmo registra al medir (pvsim/static_plant.py: set_tag).
# ---------------------------------------------------------------------------------------------------------------
_R = lambda t: "<p class='rev'>" + t + "</p>"
REVISION = {
 "msapso": _R("<b>Revisión pedida por el profesor: el primer muestreo.</b> Las 7 partículas se piden en 0.10, 0.15, 0.30, 0.50, 0.65, 0.80 y 0.95 de Isc, pero las más bajas caen en la zona gris (V/I &gt; 12 Ω) y el convertidor las mide cerca del borde: los círculos huecos marcan la corriente pedida y la línea punteada lleva al punto realmente medido. La primera medición además suele arrastrar la corriente anterior. En la práctica el enjambre arranca con 4 o 5 posiciones distintas, no 7.")
         + _R("<b>Pendiente.</b> Decidir si sembrar las partículas solo dentro del rango alcanzable (la variante «DecentCEM · barrido en zona alcanzable» mide cuánto se ganaría con un barrido así)."),
 "v7": _R("<b>Revisión pedida por el profesor: el primer muestreo.</b> Usa el mismo arranque que el MSAPSO, así que hereda el problema: las corrientes pedidas más bajas se miden en el borde de la zona gris. <i>Hipótesis por verificar:</i> como la V7 se detiene hacia la pasada 10, un arranque mal repartido pesa más que en el MSAPSO, que tiene 25 pasadas para corregirlo."),
 "v7b": _R("Mismo arranque que el MSAPSO y la V7 (ver su revisión)."),
 "cem": _R("<b>Revisión pedida por el profesor: la población inicial y cada iteración.</b> Cada color es una iteración de 10 candidatos: morado la primera, muestreada de N(0.5, 0.3²); de ámbar a azul las siguientes. La pregunta es si falla porque <b>nunca muestrea cerca del pico global</b> o porque <b>lo muestrea y la actualización lo descarta</b>: si en alguna iteración un punto cae cerca del rombo verde y la población siguiente se aleja, es lo segundo.")
       + _R("<b>Ojo.</b> Los candidatos pedidos dentro de la zona gris se miden en el borde (círculo hueco → punto), pero la gaussiana se actualiza con la posición <i>pedida</i>, no con la medida."),
 "mlp": _R("<b>Revisión pedida por el profesor: entrada de la red.</b> En esta versión el MLP recibe solo las 7 potencias del barrido (normalizadas) y la mayor relativa a la nominal; <b>no recibe las corrientes</b>. Además se entrenó con curvas estáticas midiendo exactamente en las 7 corrientes pedidas, mientras que en el simulador las más bajas se miden en el borde de 12 Ω (círculos huecos). Al darle a esta red las potencias que realmente se miden con ese borde, su error medio al ubicar el pico sube de 0.06 a 0.53 de Isc: la red ve en operación algo muy distinto de lo que vio al entrenar.")
       + _R("<b>Variante nueva.</b> «MLP + CEM con pares (I, P)» recibe los pares (corriente medida, potencia) y se entrenó con el borde de 12 Ω."),
 "cedgo": _R("<b>Revisión pedida por el profesor: por qué se detiene antes del máximo.</b> El color es la generación (8 individuos; 5 generaciones = 40 mediciones), la forma es el grupo (● grupo 1, ■ grupo 2), las cabezas llevan borde oscuro y los ▲ son <b>reemplazos por tiempo de vida</b>: cuando un individuo lleva 3 generaciones sin mejorar se reemplaza y se mide de inmediato. Por eso hay búsquedas de 41 a 46 mediciones.")
       + _R("<b>Candidatas a explicar la convergencia prematura</b> (para verificar en las corridas): (1) el vuelo de Lévy mueve cada cabeza en proporción a su distancia al mejor global, α₀·(H − b), así que la cabeza que <i>es</i> el mejor global nunca se mueve; (2) el presupuesto es fijo, 5 generaciones, sin criterio de convergencia; (3) los miembros muestrean una gaussiana por grupo con σ inicial 0.1 que se contrae con los 2 mejores. Qué mirar: si en las generaciones 4–5 los puntos siguen dispersos (falta presupuesto) o si ya se juntaron sobre un pico local desde la 2–3 (convergencia prematura)."),
 "decent": _R("<b>Revisión pedida por el profesor: creación de los workers y muestreo uniforme.</b> El barrido ya es uniforme en la corriente <i>pedida</i>: 10 puntos a la misma distancia entre 0.10 y 0.95 de Isc. Pero los que caen en la zona gris se miden en el borde, así que los puntos <i>medidos</i> no quedan parejos (círculos huecos → puntos).")
       + _R("<b>Workers.</b> Morado = barrido; un color por worker. Los workers salen de los 3 mejores puntos del barrido que estén separados más de 0.15 en la corriente <i>pedida</i> (máximo 3), y se turnan: 4 muestras de cada uno por iteración. Como la separación se mide en lo pedido, dos workers pueden medir el mismo punto físico en el borde y uno se desperdicia; también puede quedar un pico real sin worker si está a menos de 0.15 de otro.")
       + _R("<b>Variante nueva.</b> «DecentCEM · barrido en zona alcanzable» reparte los 10 puntos a la misma distancia, pero solo dentro de la zona alcanzable."),
}
for _k, _v in REVISION.items():
    FICHA[_k] = FICHA[_k] + _v

FICHA["mlp_pares"] = ("<p><b>Qué es.</b> El MLP + CEM de la V11 con el cambio que pidió el profesor: la red recibe los <b>pares (corriente medida, potencia)</b> de las 7 mediciones del barrido, no solo las potencias. "
    "Se entrenó con la misma receta (30 000 sombras sintéticas, semilla 1111, capas 64 × 64, etiqueta = corriente del máximo teórico / Isc), pero cada corriente pedida por debajo del borde alcanzable (V/I = 12 Ω) se mide en el borde, como pasa con el convertidor real. El CEM que refina es idéntico al de la V11.</p>"
    "<p><b>Qué se quiere saber.</b> Si darle a la red lo que realmente mide el convertidor corrige el desajuste entre entrenamiento y operación que se ve en la V11, y si eso baja su cola.</p>"
    "<p><b>Reservas.</b> El entrenamiento usa el borde estático (sin la inercia del convertidor); en operación la corriente medida también arrastra la anterior. La cola estática se mide con la planta estática, que no tiene borde: ahí la red recibe corrientes que no vio al entrenar.</p>")
FICHA["decent_alc"] = ("<p><b>Qué es.</b> El DecentCEM de la V17 con el muestreo que pidió el profesor: los 10 puntos del barrido <b>a la misma distancia entre sí, pero solo dentro de la zona alcanzable</b> (desde el borde V/I = 12 Ω hasta 0.95 de Isc). Workers, σ fija y presupuesto, idénticos.</p>"
    "<p><b>Importante: es un oráculo.</b> El borde se calcula con la curva verdadera, que un controlador real no conoce. Sirve como cota superior: si ni con el borde exacto mejora, no vale la pena diseñar cómo estimarlo. Se probó estimarlo midiendo (pedir corriente 0 y leer la corriente del panel) y no es confiable: con esperas de 2 ms o menos el convertidor no llega al borde en una medición.</p>")
SHORT.update({"mlp_pares": "MLP con pares (I, P) + CEM · ~37", "decent_alc": "Barrido parejo en zona alcanzable (oráculo) · ~31"})

# Resultado de la revision (campañas corridas en nov. 2026, Linux, nucleo del convertidor en C equivalente a numba; ver docs/revision_profesor.md)
FICHA["mlp_pares"] += ("<p class='rev'><b>Qué salió.</b> En la cola estática con el borde de 12 Ω mejora mucho al MLP original (p99 6.9 contra 15.3 pp): darle las corrientes sí ayuda cuando el convertidor llega a donde se le pide. "
    "En la dinámica, en cambio, pierde: −6.6 pp de energía frente a la V7 en la confirmación, sobre todo con esperas cortas (−18 pp a 0.5 ms; +1.2 pp a 5 ms, contra +2.5 pp del MLP original). "
    "<i>Interpretación:</i> con esperas cortas la corriente medida va rezagada respecto de la pedida y la red recibe pares que nunca vio al entrenar. Siguiente paso posible: entrenarla con barridos del simulador dinámico.</p>")
FICHA["decent_alc"] += ("<p class='rev'><b>Qué salió.</b> En la cola estática con el borde de 12 Ω es el mejor método de todos (pérdida media 0.05 pp, p99 1.2 pp, con 31 mediciones). "
    "En la dinámica pierde −6.3 pp frente a la V7 en la confirmación (−2.0 pp a 5 ms; −14.6 pp a 0.5 ms). <i>Hipótesis:</i> al comprimir el barrido, los 3 mejores puntos quedan a menos de 0.15 entre sí y se crea un solo worker; "
    "con la corriente rezagada de la dinámica, si ese worker cae en el pico equivocado no hay otro que lo corrija. Probar el umbral de separación proporcional al espaciado.</p>")
FICHA["v14"] += ("<p class='rev'><b>Revisión: la cola depende de cómo se mida.</b> Con la cola estática con el borde de 12 Ω (lo pedido en la zona inalcanzable se mide en el borde y se compara contra el máximo alcanzable), "
    "la V14 tiene pérdida media 0.41 pp y p99 1.4 pp, es decir, <b>cumpliría</b> el umbral de cola que no cumple en la cola oficial (p99 13 pp). La cola oficial premia al MSAPSO por encontrar picos que el convertidor no puede alcanzar. "
    "Sin embargo, su peor caso dinámico (escenario 1822) sí ocurre con el convertidor. Conviene que el equipo revise este criterio antes de cerrar la conclusión sobre la V14.</p>")
